{
  "name": "光谱仪",
  "name_en": "Spectrometer",
  "manufacturer": "",
  "description": "通用光谱仪设备，用于采集光谱数据、读取序列号、查询或设置积分时间，并可将光谱显示或保存到磁盘。",
  "description_en": "A generic spectrometer used to acquire spectral data, read the serial number, get or set integration time, and display or save spectra to disk.",
  "actions": [
    {
      "action_name": "auto-getSerialNumber",
      "description": "获取光谱仪序列号。",
      "description_en": "Get the spectrometer serial number."
    },
    {
      "action_name": "auto-getSpectrum",
      "description": "采集光谱数据。",
      "description_en": "Acquire a spectrum."
    },
    {
      "action_name": "auto-display",
      "description": "显示当前光谱数据。",
      "description_en": "Display the current spectrum."
    },
    {
      "action_name": "auto-getIntegrationTime",
      "description": "获取积分时间设置。",
      "description_en": "Get the integration time setting."
    },
    {
      "action_name": "auto-setIntegrationTime",
      "description": "设置积分时间。",
      "description_en": "Set the integration time."
    },
    {
      "action_name": "auto-saveSpectrum",
      "description": "将光谱数据保存为文件。",
      "description_en": "Save spectrum data to a file."
    }
  ],
  "tag_hints": [
    "spectroscopy",
    "spectral acquisition",
    "integration time control",
    "USB spectrometer",
    "spectrum visualization",
    "CSV export"
  ]
}

